 31	function parseCodexTapes(stdout, stderr, requestedModel) {
 32	  const frames = [];
 33	  const events = [];
 34	  const parseErrors = [];
 35	  for (const line of String(stdout).split('\n').filter(Boolean)) {
 36	    try {
 37	      const frame = JSON.parse(line);
 38	      if (frame && typeof frame === 'object' && !Array.isArray(frame)) frames.push(frame);
 39	      else parseErrors.push('invalid_exec_frame');
 40	    } catch { parseErrors.push('invalid_exec_jsonl'); }
 41	  }
 42	  for (const line of String(stderr).split('\n')) {
 43	    const offset = line.indexOf('SSE event: ');
 44	    if (offset < 0) continue;
 45	    const payload = line.slice(offset + 'SSE event: '.length);
 46	    if (payload === '[DONE]') continue;
 47	    try {
 48	      const event = JSON.parse(payload);
 49	      if (event && typeof event === 'object' && !Array.isArray(event)) events.push(event);
 50	      else parseErrors.push('invalid_provider_event');
 51	    } catch { parseErrors.push('invalid_provider_sse'); }
 52	  }
 53	  const observations = events.filter(event => event.response).map(event => ({
 54	    event: event.type, responseId: event.response.id, model: event.response.model || null,
 55	  }));
 56	  const completed = events.filter(event => event.type === 'response.completed');
 57	  const models = [...new Set(observations.map(item => item.model).filter(Boolean))];
 58	  const identityVerified = completed.length > 0 && observations.every(item => item.model === requestedModel);
 59	  const calls = events.filter(event => event.type === 'response.output_item.done'
 60	    && ['function_call', 'custom_tool_call'].includes(event.item && event.item.type))
 61	    .map(event => ({ id: event.item.call_id, name: event.item.name,
 62	      arguments: event.item.arguments === undefined ? event.item.input : event.item.arguments,
 63	      status: 'requested' }));
 64	  const catalogs = events.filter(event => Array.isArray(event.response?.tools));
 65	  const names = (tool, prefix = '') => {
 66	    if (!tool || typeof tool !== 'object' || typeof tool.name !== 'string') {
 67	      parseErrors.push('[REDACTED]');
 68	      return [];
 69	    }
 70	    if (tool.type !== 'namespace') return [prefix + tool.name];
 71	    if (!Array.isArray(tool.tools)) {
 72	      parseErrors.push('invalid_provider_tool_namespace');
 73	      return [];
 74	    }
 75	    return tool.tools.flatMap(child => names(child, prefix + tool.name + '.'));
 76	  };
 77	  const available = [...new Set(catalogs.flatMap(event => event.response.tools.flatMap(tool => names(tool))))];
 78	  const tools = {
 79	    enabled: true,
 80	    available,
 81	    availability_status: catalogs.length ? 'provider_response_catalog' : '[REDACTED]',
 82	    calls,
 83	    total: calls.length,
 84	    succeeded: null,
 85	    failed: null,
 86	    outcome_status: 'see_exec_events_and_raw_tapes',
 87	    execution_events: frames.filter(frame => frame.item && frame.item.type !== 'agent_message'),
 88	  };
 89	  const answer = frames.filter(frame => frame.type === 'item.completed' && frame.item && frame.item.type === 'agent_message')
 90	    .map(frame => frame.item.text).at(-1) || '';
 91	  const complete = frames.some(frame => frame.type === 'turn.completed');
 92	  return { frames, events, parseErrors, observations, models, completed, identityVerified, tools, answer, complete };
 93	}
